import Foundation

struct OverrideGroup: Identifiable {
    let title: String
    let labels: [String]
    var dependencies: [String] = []
    var note: String = ""
    var controlsAirDrop = false
    var id: String { title }

    var allLabels: [String] {
        var seen = Set<String>()
        return (labels + dependencies).filter { seen.insert($0).inserted }
    }

    // Core prerequisites are restored by On but managed in the Critical tab.
    var visibleLabels: [String] {
        allLabels.filter { !SafetyManager.isCritical($0) }
    }

    func actionLabels(enable: Bool) -> [String] {
        enable ? allLabels : allLabels.filter {
            labels.contains($0) && !SafetyManager.isCritical($0)
        }
    }
}

enum OverrideServices {
    // Core OS services are assumed available; these are feature-specific jobs
    // and known shared prerequisites, not a complete OS dependency graph.
    static let groups = [
        OverrideGroup(title: "Background sounds and hearing", labels: ["com.apple.accessibility.heard"], dependencies: ["com.apple.mediaserverd"], note: "HearingCore provides Background Sounds and other hearing features. Defaults On for regular Background Sounds use. Off remains available and stops these features; Bluetooth alone does not provide them. The shared audio service remains enabled. Restart userspace after changes."),
        OverrideGroup(title: "Drag and drop", labels: ["com.apple.DragUI.druid"], note: "Controls the drag-and-drop broker for source, destination and paste-announcement services. Defaults On for regular drag-and-drop use; manual Off remains available. Restart userspace after changes."),
        OverrideGroup(title: "Auto-Lock and configuration policy", labels: ["com.apple.managedconfiguration.profiled"], note: "Recommended On for native Auto-Lock, Low Power Mode restrictions, configuration profiles and managed feature settings. Off remains available and can leave Auto-Lock greyed out or stuck at a stale 30-second limit, as observed on iOS 16.7.16. This controls only profiled, not the separate enrollment or passcode-prompt services. Restart userspace after either change; re-enable this group before changing Auto-Lock or using Duskie’s normal-timeout option."),
        OverrideGroup(title: "Core logging", labels: ["com.apple.logd", "com.apple.logd_helper"], note: "Controls the unified logger and its maintenance helper. Both default On. Off stops the listed logging jobs and has not been tested as a complete logger-Off profile. The helper alone passed basic use and a short screen-off CPU check, but long-term rotation/cleanup remain unverified. Measured logging cost was small; no RAM or battery gain is established. Restart userspace after either change."),
        OverrideGroup(title: "Analytics and diagnostics", labels: ["com.apple.analyticsd", "com.apple.aggregated", "com.apple.aggregated.addaily", "com.apple.diagnosticd", "com.apple.diagnosticextensionsd", "com.apple.iosdiagnosticsd", "com.apple.osanalytics.osanalyticshelper", "com.apple.powerlogHelperd", "com.apple.syslogd", "com.apple.sysdiagnose", "com.apple.sysdiagnose_helper", "com.apple.spindump", "com.apple.ReportCrash", "com.apple.ReportMemoryException", "com.apple.crash_mover"], dependencies: ["com.apple.logd", "com.apple.logd_helper"], note: "Groups optional analytics, legacy logging, crash/resource reporting and diagnostic collectors. These collectors already default Off in the tested profile. On restores them and core logging for troubleshooting; collection can add CPU, RAM and disk work. Off preserves core logging. This does not control every kernel/app logging path or all network-specific diagnostics. Restart userspace after changes. The complete group On/recovery cycle is unverified."),
        OverrideGroup(title: "Bluetooth helpers", labels: ["com.apple.bluetoothuserd", "com.apple.BluetoothUIService", "com.apple.BTServer.le", "com.apple.BTServer.avrcp", "com.apple.BTServer.map", "com.apple.BTServer.pbap"], dependencies: ["com.apple.bluetoothd", "com.apple.BlueTool", "com.apple.WirelessRadioManager"], note: "Controls optional Bluetooth user/UI and profile jobs. Critical bluetoothd and BlueTool are preserved: disabling bluetoothd reproduced a mediaserverd/launchd retry flood, while disabling BlueTool caused bluetoothd to consume one CPU core. Both appear only in Critical. Use Settings > Bluetooth for ordinary Bluetooth On/Off. Off can break pairing, audio and accessories and is not complete Bluetooth removal or a hardware radio power switch. The shared radio coordinator stays enabled for Wi-Fi/cellular. The revised profile passed a short Off/restart/recovery CPU/core-health check on iPhone 8 Plus/iOS 16.7.16. Accessory behavior and battery benefit are unverified."),
        OverrideGroup(title: "Calls and SMS", labels: ["com.apple.CommCenterMobileHelper", "com.apple.CommCenterRootHelper", "com.apple.telephonyutilities.callservicesd", "com.apple.imagent", "com.apple.identityservicesd", "com.apple.imcore.imtransferagent", "com.apple.ids.IDSCredentialsAgent", "com.apple.idsfoundation.IDSRemoteURLConnectionAgent", "com.apple.voicemail.vmd", "com.apple.avconferenced"], dependencies: ["com.apple.cmfsyncagent", "com.apple.CommCenter", "com.apple.nehelper", "com.apple.apsd", "com.apple.accountsd", "com.apple.akd", "com.apple.WirelessRadioManager"], note: "CommunicationsFilter sync is a shared prerequisite for the tested carrier SMS/contact-detail paths and stays enabled on group Off. Controls call/SMS helpers, CallKit/VoIP and messaging brokers. Off can break calls, SMS, VoIP and account verification. Shared CommCenter stays enabled: removing it caused repeated SpringBoard CoreTelephony connection failures, stopped by restoring only CommCenter. Shared push/account/network prerequisites also stay enabled. This does not disable the cellular radio or guarantee removal of every telephony process. Restart userspace in either direction. The revised profile passed a short Off/restart/recovery CPU/core-health check on iPhone 8 Plus/iOS 16.7.16; this is not validation of every app or overnight task."),
        OverrideGroup(title: "Wi-Fi", labels: ["com.apple.wifid", "com.apple.wifiFirmwareLoader", "com.apple.wifip2pd", "com.apple.wifi.hostapd", "com.apple.wifi.wapic", "com.apple.wifianalyticsd", "com.apple.wifivelocityd"], dependencies: ["com.apple.configd", "com.apple.WirelessRadioManager"], note: "Off disables Wi-Fi service jobs after userspace restart and can disconnect Wi-Fi SSH. Restore On locally in this app or through working USB SSH. Shared network configuration and radio coordination stay enabled for other transports. This does not guarantee that the hardware radio is powered off. The listed jobs passed a short Off/restart/recovery CPU/core-health check on iPhone 8 Plus/iOS 16.7.16. This does not establish overnight or full-kernel-boot behavior."),
        OverrideGroup(title: "Keyboard", labels: ["com.apple.TextInput.kbd", "com.apple.handwritingd", "com.apple.naturallanguaged", "com.apple.fullkeyboardaccess"], dependencies: ["com.apple.biomed", "com.apple.cfprefsd.xpc.daemon"], note: "Off deliberately disables text-input services after userspace restart. Typing, AutoFill, text replacement and keyboard clients can fail; restore On locally without relying on keyboard entry. InputUI is a separate shared interface host and is not disabled. The listed Off profile passed a short CPU/core-health check and was restored successfully on iPhone 8 Plus/iOS 16.7.16."),
        OverrideGroup(title: "Safari services", labels: ["com.apple.WebBookmarks.webbookmarksd", "com.apple.Safari.History", "com.apple.Safari.SafeBrowsing.Service", "com.apple.Safari.passwordbreachd", "com.apple.SafariBookmarksSyncAgent", "com.apple.safarifetcherd", "com.apple.webkit.webpushd", "com.apple.webkit.adattributiond"], dependencies: ["com.apple.nsurlsessiond", "com.apple.security.swcagent"], note: "Groups Safari bookmarks/history, sync, website checks, Reading List, web push and attribution. The Safari app and WebKit content/network/GPU processes are app/XPC processes, not these launchd jobs: Off does not block browsing or eliminate every browser process. Shared networking and associated-domain services stay enabled. Restart userspace after changes."),
        OverrideGroup(title: "Location", labels: ["com.apple.locationd", "com.apple.gpsd", "com.apple.geod", "com.apple.navd", "com.apple.locationpushd", "com.apple.routined", "com.apple.maps.destinationd", "com.apple.Maps.geocorrectiond", "com.apple.Maps.mapspushd"], note: "Off includes Core Location and GPS, geocoding/navigation, location push and routine services. Location-dependent apps and automatic location features can fail. On restores the listed jobs; restart userspace in either direction. Full Off/recovery has not been tested on this profile."),
        OverrideGroup(title: "Dictation", labels: ["com.apple.assistantd", "com.apple.corespeechd"], dependencies: ["com.apple.TextInput.kbd", "com.apple.mediaserverd"], note: "Keyboard microphone dictation. On the tested iPhone 8 Plus/iOS 16.7.16, assistantd alone failed, the pair worked, and corespeechd alone failed. Both provide shared Siri/speech infrastructure; this is not an independent dictation-only process. Turn on Settings > General > Keyboard > Enable Dictation. Other Siri, training, suggestion and Shortcuts jobs remain unchanged. Off removes this speech path and can also affect Siri. Both default Off; group On restores them without changing their default targets. Restart userspace if a keyboard client retains a failed connection."),
        OverrideGroup(title: "Siri", labels: ["com.apple.assistant_service", "com.apple.assistant_cdmd", "com.apple.siriinferenced", "com.apple.siriknowledged", "com.apple.sirittsd", "com.apple.speechmodeltrainingd", "com.apple.siriactionsd", "com.apple.ShortcutsUI", "com.apple.triald"], dependencies: ["com.apple.assistantd", "com.apple.corespeechd", "com.apple.linkd", "com.apple.pluginkit.pkd"], note: "Trial is required for the tested US English Voice 5 download; its asset request stalled with triald disabled and began downloading after enable/bootstrap without reboot. Voice assistance, Siri context, speech output/training and the shared VoiceShortcuts broker. On restores shared speech prerequisites; Off preserves assistantd/corespeechd so the separate Dictation group can remain On. Off also stops Shortcuts/automations using siriactionsd. Disable Siri activation in Settings if you want dictation without invoking Siri. Spotlight and CoreDuet scheduling are shared system services. Restart userspace after changes."),
        OverrideGroup(title: "Spotlight and search", labels: ["com.apple.corespotlightservice", "com.apple.spotlight.IndexAgent", "com.apple.spotlightknowledged", "com.apple.parsecd", "com.apple.parsec-fbf", "com.apple.knowledgeconstructiond"], dependencies: ["com.apple.searchd"], note: "Controls optional search, indexing and knowledge helpers, separately from Siri and dictation. Turning them off can reduce indexed or suggested results; the Spotlight interface and app-local search can remain available. Shared system prerequisites remain managed in Critical. Restart userspace after changes."),
        OverrideGroup(title: "Wallpaper", labels: ["com.apple.PosterBoard", "com.apple.PaperBoard"], note: "Controls wallpaper and Lock Screen hosts. PosterBoard is also required for the tested Lock Screen media controls. Group Off can break their rendering even with liveactivitiesd on. Restart userspace after changes."),
        OverrideGroup(title: "Lock Screen media controls", labels: ["com.apple.PosterBoard", "com.apple.liveactivitiesd"], note: "Both default Off and remain freely switchable. On restores the tested Lock Screen and Notification Center playback panel; Off disables both hosts. liveactivitiesd also supports Live Activities, and PosterBoard is shared with Wallpaper. PaperBoard was not required in the tested profile. Control Center playback controls worked with both off. Restart userspace after changes: repeated MediaRemoteUI rendering failures survived resprings."),
        OverrideGroup(title: "Accessibility and captions", labels: ["com.apple.AccessibilityUIServer", "com.apple.livetranscriptionui", "com.apple.assistivetouchd", "com.apple.VoiceOverTouch", "com.apple.accessibility.axassetsd", "com.apple.accessibility.axremoted", "com.apple.accessibility.motiontrackingd", "com.apple.commandandcontrol", "com.apple.fullkeyboardaccess", "com.apple.scrod", "com.apple.voiced"], dependencies: ["com.apple.mediaserverd"], note: "Optional accessibility UI, AssistiveTouch, VoiceOver, Voice Control, keyboard access, recognition, remote accessibility and spoken-content jobs. These default Off. Group Off stops these features; shared audio remains enabled. Background Sounds/heard is intentionally separate and stays On for regular sleep use. Spoken content and AssistiveTouch also have focused groups. Use Apply Now to attempt loading/unloading in this session; clients can require reopening or a restart."),
        OverrideGroup(title: "AssistiveTouch", labels: ["com.apple.assistivetouchd"], dependencies: ["com.apple.AccessibilityUIServer", "com.apple.backboardd"], note: "Restores the AssistiveTouch service and its accessibility UI host. Enable AssistiveTouch in Settings as well; a daemon override is separate from that feature switch. Defaults Off; group Off preserves the shared UI prerequisite."),
        OverrideGroup(title: "Speak Screen and spoken content", labels: ["com.apple.voiced", "com.apple.accessibility.axassetsd"], dependencies: ["com.apple.AccessibilityUIServer", "com.apple.sirittsd", "com.apple.triald", "com.apple.mobileassetd", "com.apple.mediaserverd"], note: "On-demand spoken content, speech output and voice asset support. Defaults Off. Enable Speak Screen in Settings too. Siri speech/Trial, audio and the accessibility UI host are shared prerequisites and remain enabled on group Off. Voice/language coverage must be checked on the device."),
        OverrideGroup(title: "CarPlay", labels: ["com.apple.CarPlayApp", "com.apple.carkitd"], note: "CarPlay interface and vehicle integration, both default Off. Normal phone calling and core Bluetooth remain independent shared services."),
        OverrideGroup(title: "Handoff", labels: ["com.apple.coreservices.useractivityd"], dependencies: ["com.apple.rapportd", "com.apple.sharingd"], note: "NSUserActivity/Handoff support defaults Off. Shared discovery and sharing stay available; this is not complete removal of all continuity functionality. The Settings Handoff switch is separate."),
        OverrideGroup(title: "Apple Watch helpers", labels: ["com.apple.companion_proxy", "com.apple.companionauthd", "com.apple.nanobackupd", "com.apple.nanoprefsyncd", "com.apple.nanoprefsyncd.2", "com.apple.nanoregistrylaunchd", "com.apple.nanotimekitcompaniond", "com.apple.subridged", "com.apple.watchpresenced", "com.apple.wcd"], dependencies: ["com.apple.nanoregistryd"], note: "Optional Watch pairing, backup, sync and app connectivity helpers, all default Off. The shared registry remains Critical because earlier evidence records a boot failure when disabled. System watchdogd is unrelated and stays enabled."),
        OverrideGroup(title: "Nearby accessories and AirPods", labels: ["com.apple.proximitycontrold", "com.apple.cloudpaird"], dependencies: ["com.apple.bluetoothd", "com.apple.BlueTool"], note: "Optional proximity interfaces and iCloud Bluetooth pairing support, both default Off. Shared Bluetooth controller/audio infrastructure remains enabled; this does not switch off the Bluetooth radio."),
        OverrideGroup(title: "USB and wired accessories", labels: ["com.apple.afcd", "com.apple.mobile.house_arrest", "com.apple.mobile.notification_proxy", "com.apple.mobile.insecure_notification_proxy", "com.apple.accessoryd", "com.apple.iapd", "com.apple.iap2d", "com.apple.iapauthd", "com.apple.usb.networking.addNetworkInterface"], dependencies: ["com.apple.mobile.lockdown", "com.openssh.sshd"], note: "Groups computer file access, host notifications, wired accessory protocols and USB network setup. On restores these jobs plus shared pairing and SSH prerequisites; Off preserves the shared lockdownd and OpenSSH prerequisites. These jobs are not all required for USB SSH, and Off does not disable the USB controller or wall charging. Restart userspace after changes. The earlier USB recovery followed a full override reset and restart; no single service was isolated as its cause."),
        OverrideGroup(title: "AirDrop", labels: ["com.apple.sharing.airdropui"], dependencies: ["com.apple.sharingd", "com.apple.pluginkit.pkd"], note: "On/Off also changes Allow AirDrop for sending and receiving. Shared sharingd and pkd remain enabled for other app extensions and sharing.", controlsAirDrop: true),
        OverrideGroup(title: "Wallet", labels: ["com.apple.PassbookUISceneService", "com.apple.passd"], note: "Wallet interface and shared PassKit backend. Off disables both listed jobs, including Recommended On passd. This also breaks the tested App Store confirmation path; enable Wallet or App Store again to restore passd. Apple Pay and Wallet passes were not tested."),
        OverrideGroup(title: "Shortcuts", labels: ["com.apple.ShortcutsUI", "com.apple.linkd"], dependencies: ["com.apple.siriactionsd", "com.apple.pluginkit.pkd"], note: "Includes interactive UI and the app-action broker. Apple’s Set Flashlight action passed testing; the WhatsApp Meta AI action remains unresolved. Restart userspace after group changes."),
        OverrideGroup(title: "Screen recording", labels: ["com.apple.replaykitangel", "com.apple.replayd"], note: "Enable both, then respring before recording: SpringBoard retained a broken connection until respring in device tests. Screen capture/broadcast is separate from Camera photos and videos."),
        OverrideGroup(title: "Widget updates", labels: ["com.apple.chronod"], dependencies: ["com.apple.pluginkit.pkd"], note: "Stops widget timeline updates; does not remove configured widgets or disable every legacy widget path. Keep pkd on to avoid the reproduced CPU loop. Live Activities and Lock Screen playback are controlled by the separate media group."),
        OverrideGroup(title: "Apple Account and settings sync", labels: ["com.apple.appleaccountd", "com.apple.amsaccountsd", "com.apple.cloudsettingssyncagent", "com.apple.cloudd"], dependencies: ["com.apple.cmfsyncagent", "com.apple.accountsd", "com.apple.akd", "com.apple.adid", "com.apple.absd", "com.apple.cdpd", "com.apple.followupd", "com.apple.identityservicesd", "com.apple.imagent", "com.apple.syncdefaultsd", "com.apple.apsd", "com.apple.protectedcloudstorage.protectedcloudkeysyncing", "com.apple.SecureBackupDaemon"], note: "CommunicationsFilter sync is a shared prerequisite for the tested carrier SMS/contact-detail paths and stays enabled on group Off. Full Apple Account sign-in passed on the test phone with the listed authentication jobs restored, including imagent for SMS codes, and a userspace restart. The final cdpd/followupd/Identity Services set was tested together, not individually isolated. Group Off disables the listed Apple Account jobs and preserves shared prerequisite-only authentication jobs. Sign-in and account functionality can fail; no safe complete-account-Off claim is made. Cloud sync needs separate verification. Restart userspace after changes."),
        OverrideGroup(title: "Messages and FaceTime", labels: ["com.apple.imagent", "com.apple.identityservicesd"], dependencies: ["com.apple.cmfsyncagent", "com.apple.avconferenced", "com.apple.nehelper", "com.apple.apsd", "com.apple.accountsd", "com.apple.akd"], note: "CommunicationsFilter sync is a shared prerequisite for the tested carrier SMS/contact-detail paths and stays enabled on group Off. Restoring imagent plus respring restored carrier SMS verification delivery. Group Off disables imagent and Identity Services as an intentional messaging opt-out, including carrier SMS verification and related account flows. Both remain Recommended On by default. AVConference stays enabled as a shared callservicesd prerequisite: disabling it alone reproduced continuous invalid-connection retries while calls remained enabled. Nehelper restored Messages in earlier tests; FaceTime calls remain untested. Restart userspace after changes."),
        OverrideGroup(title: "iCloud Drive", labels: ["com.apple.bird", "com.apple.cloudd"], dependencies: ["com.apple.FileProvider", "com.apple.accountsd", "com.apple.akd", "com.apple.protectedcloudstorage.protectedcloudkeysyncing", "com.apple.SecureBackupDaemon"], note: "CloudDocs and CloudKit sync. Shared FileProvider remains available for local Files and sharing. Restoring the protected-key and secure-backup prerequisites repaired key recovery in logs; Drive listing, upload and web download passed on the test phone; one initial Save to Files attempt unexpectedly returned Home and was not isolated. Complete any Settings account verification and restart userspace after changes."),
        OverrideGroup(title: "Photos sharing and export", labels: ["com.apple.photos.ImageConversionService", "com.apple.photos.VideoConversionService"], dependencies: ["com.apple.assetsd", "com.apple.pluginkit.pkd", "com.apple.sharingd"], note: "Restoring ImageConversionService and respringing repaired Photos → WhatsApp image export. Restoring VideoConversionService separately and respringing then repaired the Camera video test. Both remain Recommended On by default. Group Off deliberately stops both conversion jobs, disabling exports that need them; their recorded export failures are functionality loss, not evidence of a bootloop. Camera capture is separate from sharing conversion. Restart userspace after group changes."),
        OverrideGroup(title: "iCloud Photos", labels: ["com.apple.cloudphotod", "com.apple.assetsd.nebulad"], dependencies: ["com.apple.assetsd", "com.apple.cloudd", "com.apple.accountsd", "com.apple.akd", "com.apple.protectedcloudstorage.protectedcloudkeysyncing", "com.apple.SecureBackupDaemon", "com.apple.dasd", "com.apple.contextstored"], note: "Photos cloud-sync jobs; shared Photos storage remains available for local capture. Restoring the key/backup prerequisites and contextstored, then allowing the scheduled retry, synced two user-verified photos. Turning only contextstored back off and restarting reproduced a new upload stall: DAS rejected it on network-quality/data-budget policies while context reads failed. Group Off preserves these shared prerequisite-only jobs, including Recommended On context/key recovery and Critical dasd. Complete any Settings account verification and restart userspace after changes."),
        OverrideGroup(title: "App Store and media purchases", labels: ["com.apple.appstored", "com.apple.appstorecomponentsd", "com.apple.itunesstored", "com.apple.amsaccountsd", "com.apple.amsengagementd"], dependencies: ["com.apple.accountsd", "com.apple.akd", "com.apple.adid", "com.apple.passd", "com.apple.storekitd"], note: "Store downloads and media accounts, separate from TrollStore installation. Restoring passd and respringing repaired a free-app download, installation and launch. A second new free app also passed after amsengagementd was turned back off; it remains optional for other Media Services prompts. Group Off preserves prerequisite-only passd, which remains Recommended On. Paid purchases remain untested. Restart userspace after changes."),
        OverrideGroup(title: "Contacts and calendars", labels: ["com.apple.contactsd", "com.apple.calaccessd", "com.apple.dataaccess.dataaccessd"], dependencies: ["com.apple.accountsd"], note: "Address book, calendar access and configured account sync. Disabling affects apps using these stores; sync was not tested. Restart userspace after changes.")
    ].sorted { $0.title.localizedCaseInsensitiveCompare($1.title) == .orderedAscending }
    static let springBoardInterfacesTitle = "SpringBoard interfaces"
    static let menuTitles = (groups.map(\.title) + [springBoardInterfacesTitle]).sorted {
        $0.localizedCaseInsensitiveCompare($1) == .orderedAscending
    }

    static func actionLabels(for groups: [OverrideGroup], enable: Bool) -> [String] {
        var seen = Set<String>()
        return groups.flatMap { $0.actionLabels(enable: enable) }.filter { seen.insert($0).inserted }
    }

    // Only these jobs are automatically loaded/unloaded after a toggle. Other jobs
    // save overrides first; explicit Apply Now attempts their session change.
    static let labels: Set<String> = [
        "com.apple.PosterBoard", "com.apple.PaperBoard", "com.apple.AccessibilityUIServer",
        "com.apple.livetranscriptionui", "com.apple.sharing.airdropui", "com.apple.PassbookUISceneService",
        "com.apple.ShortcutsUI", "com.apple.replaykitangel", "com.apple.replayd",
        "com.apple.chronod", "com.apple.liveactivitiesd"
    ]
}
